package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000000007

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	fmt.Fscan(in, &n, &k)

	q := make([]int64, n)
	inv := make([]int64, n)

	q[0] = 1
	var sumAll int64 = 1
	var window int64 = 1

	for i := 1; i < n; i++ {
		if i == 1 {
			inv[i] = 1
		} else {
			inv[i] = (mod - (mod/int64(i))*inv[mod%int64(i)]%mod) % mod
		}

		q[i] = window * inv[i] % mod
		sumAll = (sumAll + q[i]) % mod
		window = (window + q[i]) % mod

		if i >= k {
			window = (window - q[i-k] + mod) % mod
		}
	}

	factNMinusOne := int64(1)
	for i := 2; i < n; i++ {
		factNMinusOne = factNMinusOne * int64(i) % mod
	}
	factN := factNMinusOne * int64(n) % mod

	success := factNMinusOne * sumAll % mod
	answer := (factN - success + mod) % mod

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

